//! `jsrt::number` against `fixtures/numbers.json`, generated by Node 26.

mod common;

use common::*;
use jsrt::number::{
    math_round, number_to_string, number_to_string_radix, parse_float, parse_int, string_to_number,
};
use serde_json::Value;

fn f64_of(v: &Value) -> f64 {
    let hex = v
        .as_str()
        .unwrap_or_else(|| panic!("expected bits, got {v}"));
    f64::from_bits(u64::from_str_radix(hex, 16).expect("hex bits"))
}

fn text(v: &Value) -> &str {
    v.as_str()
        .unwrap_or_else(|| panic!("expected a string, got {v}"))
}

/// Same double, bit for bit; any NaN matches any NaN.
fn assert_same(got: f64, want: f64, ctx: &str) {
    assert!(
        got.to_bits() == want.to_bits() || (got.is_nan() && want.is_nan()),
        "{ctx}: got {got:?} ({:016x}), want {want:?} ({:016x})",
        got.to_bits(),
        want.to_bits()
    );
}

fn numbers() -> Value {
    fixture("numbers.json")
}

#[test]
fn to_string() {
    let f = numbers();
    for case in arr(&f["toString"]) {
        let x = f64_of(&case[0]);
        assert_eq!(
            number_to_string(x),
            text(&case[1]),
            "String({x:?}) bits {}",
            text(&case[0])
        );
    }
}

#[test]
fn to_string_radix() {
    let f = numbers();
    for case in arr(&f["toStringRadix"]) {
        let x = f64_of(&case[0]);
        let radix = u32::try_from(int(&case[1])).unwrap();
        assert_eq!(
            number_to_string_radix(x, radix),
            text(&case[2]),
            "({x:?}).toString({radix})"
        );
    }
}

#[test]
fn parse_int_cases() {
    let f = numbers();
    for case in arr(&f["parseInt"]) {
        let s = text(&case[0]);
        let radix = i32_of(&case[1]);
        assert_same(
            parse_int(s, radix),
            f64_of(&case[2]),
            &format!("parseInt({s:?}, {radix})"),
        );
    }
}

#[test]
fn parse_float_cases() {
    let f = numbers();
    for case in arr(&f["parseFloat"]) {
        let s = text(&case[0]);
        assert_same(
            parse_float(s),
            f64_of(&case[1]),
            &format!("parseFloat({s:?})"),
        );
    }
}

#[test]
fn string_to_number_cases() {
    let f = numbers();
    for case in arr(&f["number"]) {
        let s = text(&case[0]);
        assert_same(
            string_to_number(s),
            f64_of(&case[1]),
            &format!("Number({s:?})"),
        );
    }
}

#[test]
fn math_round_cases() {
    let f = numbers();
    for case in arr(&f["mathRound"]) {
        let x = f64_of(&case[0]);
        assert_same(
            math_round(x),
            f64_of(&case[1]),
            &format!("Math.round({x:?})"),
        );
    }
}
